package com.travel.meomulkyung.itinerary.service;
import com.travel.meomulkyung.itinerary.*; import com.travel.meomulkyung.itinerary.domain.*; import com.travel.meomulkyung.itinerary.dto.*; import com.travel.meomulkyung.itinerary.repository.*; import com.travel.meomulkyung.recommendation.domain.*; import com.travel.meomulkyung.region.repository.RegionRepository; import com.travel.meomulkyung.user.repository.UserRepository; import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.*; import org.springframework.boot.data.jpa.test.autoconfigure.DataJpaTest; import org.springframework.context.annotation.Import; import java.time.*; import java.util.*; import static org.assertj.core.api.Assertions.*;
@DataJpaTest @Import({ItineraryService.class,ItineraryTestConfig.class,com.travel.meomulkyung.contribution.ContributionPolicy.class}) class ItineraryServiceTest { @Autowired ItineraryService service; @Autowired UserRepository users; @Autowired RegionRepository regions; @Autowired ItineraryRepository itineraries; @Autowired ItineraryTestConfig.FakeFestivalProvider festivals; @Autowired ItineraryTestConfig.FakeTourPlaceProvider places; @Autowired Clock clock; @BeforeEach void init(){regions.save(ItineraryTestFixture.region());festivals.setFestivals(List.of());places.reset();} List<com.travel.meomulkyung.itinerary.external.TourPlaceProvider.Place> pool(int attractions,int restaurants){List<com.travel.meomulkyung.itinerary.external.TourPlaceProvider.Place> result=new ArrayList<>();for(long id=1;id<=attractions;id++)result.add(new com.travel.meomulkyung.itinerary.external.TourPlaceProvider.Place(id,"Attraction "+id,ItineraryItemType.TOURIST_SPOT,null,null,null,null));for(long id=101;id<=100+restaurants;id++)result.add(new com.travel.meomulkyung.itinerary.external.TourPlaceProvider.Place(id,"Restaurant "+id,ItineraryItemType.RESTAURANT,null,null,null,null));return result;} ItineraryRequests.Create request(int nights){return new ItineraryRequests.Create(1L,LocalDate.now(clock),nights,List.of(PreferenceTag.FOOD),CompanionType.FRIENDS);} ItineraryRequests.Create request(LocalDate startDate,int nights){return new ItineraryRequests.Create(1L,startDate,nights,List.of(PreferenceTag.FOOD),CompanionType.FRIENDS);} Long user(){return users.save(ItineraryTestFixture.user()).getId();}
 @Test void createsDaysAndTerminalItems(){var r=service.create(user(),request(1));assertThat(r.days()).hasSize(2);assertThat(r.status()).isEqualTo("DRAFT");assertThat(r.generationVersion()).isEqualTo(1);assertThat(r.days().getFirst().items().getFirst().type()).isEqualTo("ARRIVAL");assertThat(r.days().getLast().items().getLast().type()).isEqualTo("DEPARTURE");assertThat(r.days().getFirst().items()).extracting("type").contains("REST");}
 @Test void createsEightDaysForSevenNights(){assertThat(service.create(user(),request(7)).days()).hasSize(8);}
 @Test void deniesOtherUserAndMissingItinerary(){Long owner=user();Long id=service.create(owner,request(1)).itineraryId();assertThatThrownBy(()->service.get(user(),id)).isInstanceOf(ItineraryException.class).extracting("code").isEqualTo("ITINERARY_ACCESS_DENIED");assertThatThrownBy(()->service.get(owner,999L)).isInstanceOf(ItineraryException.class).extracting("code").isEqualTo("ITINERARY_NOT_FOUND");}
 @Test void replacesOnlyReplaceableAndIncrementsVersion(){Long u=user();Long id=service.create(u,request(1)).itineraryId();Itinerary i=itineraries.findDetailById(id).orElseThrow();ItineraryItem p=i.getItems().stream().filter(ItineraryItem::isReplaceable).findFirst().orElseThrow();var r=service.replace(u,id,p.getId(),new ItineraryRequests.Replace(true));assertThat(r.generationVersion()).isEqualTo(2);assertThat(r.newItem().sequence()).isEqualTo(p.getSequence());ItineraryItem rest=i.getItems().stream().filter(x->x.getItemType()==ItineraryItemType.REST).findFirst().orElseThrow();assertThatThrownBy(()->service.replace(u,id,rest.getId(),new ItineraryRequests.Replace(false))).isInstanceOf(ItineraryException.class).extracting("code").isEqualTo("ITEM_NOT_REPLACEABLE");}
 @Test void replacesRestaurantWhenItineraryConsumedWholePool(){places.setCandidates(pool(6,4));Long u=user();Long id=service.create(u,request(1)).itineraryId();Itinerary i=itineraries.findDetailById(id).orElseThrow();assertThat(i.getItems().stream().filter(x->x.getItemType()==ItineraryItemType.RESTAURANT).map(ItineraryItem::getContentId).distinct()).hasSize(4);ItineraryItem target=i.getItems().stream().filter(x->x.getItemType()==ItineraryItemType.RESTAURANT).findFirst().orElseThrow();Long before=target.getContentId();var r=service.replace(u,id,target.getId(),new ItineraryRequests.Replace(false));assertThat(r.newItem().placeId()).isNotNull().isNotEqualTo(before);}
 @Test void replacementKeepsSameDayFreeOfDuplicates(){places.setCandidates(pool(6,4));Long u=user();Long id=service.create(u,request(1)).itineraryId();Itinerary i=itineraries.findDetailById(id).orElseThrow();ItineraryItem target=i.getItems().stream().filter(x->x.getItemType()==ItineraryItemType.RESTAURANT&&x.getDayNumber()==1).findFirst().orElseThrow();service.replace(u,id,target.getId(),new ItineraryRequests.Replace(false));assertThat(i.getItems().stream().filter(x->x.getDayNumber()==1&&x.getContentId()!=null).map(ItineraryItem::getContentId).toList()).doesNotHaveDuplicates();}
 @Test void repeatedReplacementRotatesThroughCandidates(){places.setCandidates(pool(6,4));Long u=user();Long id=service.create(u,request(1)).itineraryId();Itinerary i=itineraries.findDetailById(id).orElseThrow();ItineraryItem target=i.getItems().stream().filter(x->x.getItemType()==ItineraryItemType.RESTAURANT&&x.getDayNumber()==1).findFirst().orElseThrow();Long first=service.replace(u,id,target.getId(),new ItineraryRequests.Replace(false)).newItem().placeId();Long second=service.replace(u,id,target.getId(),new ItineraryRequests.Replace(false)).newItem().placeId();assertThat(second).isNotEqualTo(first);}
 @Test void bookmarkAndCompletionAreIdempotentOrConflict(){Long u=user();Long id=service.create(u,request(1)).itineraryId();assertThat(service.bookmark(u,id).bookmarked()).isTrue();assertThat(service.bookmark(u,id).bookmarked()).isTrue();var done=service.complete(u,id,new ItineraryRequests.Completion(24,2,100));assertThat(done.stamp().newlyAwarded()).isTrue();assertThat(done.contribution().calculationStatus()).isEqualTo("CALCULATED");assertThat(done.contribution().populationContributionDays()).isEqualTo(1);assertThatThrownBy(()->service.complete(u,id,new ItineraryRequests.Completion(24,2,100))).isInstanceOf(ItineraryException.class).extracting("code").isEqualTo("ITINERARY_ALREADY_COMPLETED");}
 @Test void weatherHasDataAtDPlus10AndIsUnavailableAtDPlus11(){Long u=user();Long dPlusTen=service.create(u,request(LocalDate.now(clock).plusDays(10),1)).itineraryId();assertThat(service.weather(u,dPlusTen).days().getFirst().available()).isTrue();Long dPlusEleven=service.create(u,new ItineraryRequests.Create(1L,LocalDate.now(clock).plusDays(11),1,List.of(PreferenceTag.FOOD),CompanionType.FRIENDS)).itineraryId();assertThat(service.weather(u,dPlusEleven).days()).allMatch(x->!x.available());}
 @Test void unbookmarkIsIdempotentAndOtherUserIsDenied(){Long u=user();Long id=service.create(u,request(1)).itineraryId();service.unbookmark(u,id);service.unbookmark(u,id);assertThatThrownBy(()->service.unbookmark(user(),id)).isInstanceOf(ItineraryException.class).extracting("code").isEqualTo("ITINERARY_ACCESS_DENIED");}
 @Test void revisitingRegionIncrementsExistingStamp(){Long u=user();Long first=service.create(u,request(1)).itineraryId();service.complete(u,first,new ItineraryRequests.Completion(24,1,0));Long second=service.create(u,request(1)).itineraryId();var response=service.complete(u,second,new ItineraryRequests.Completion(24,1,0));assertThat(response.stamp().newlyAwarded()).isFalse();assertThat(response.stamp().visitCount()).isEqualTo(2);}
 @Test void includesOverlappingFestivalWithRequiredDetails(){LocalDate start=LocalDate.of(2026,9,10);festivals.setFestivals(List.of(new com.travel.meomulkyung.itinerary.external.FestivalProvider.Festival(99L,"Autumn Festival",start.minusDays(1),start.plusDays(2),"https://image.test/festival.jpg","Festival street")));var response=service.create(user(),request(start,2));var festival=response.days().stream().flatMap(day->day.items().stream()).filter(item->item.type().equals("FESTIVAL")).findFirst().orElseThrow();assertThat(festival.festivalId()).isEqualTo(99L);assertThat(festival.title()).isEqualTo("Autumn Festival");assertThat(festival.address()).isEqualTo("Festival street");assertThat(festival.imageUrl()).isEqualTo("https://image.test/festival.jpg");assertThat(festival.eventStartDate()).isEqualTo(start.minusDays(1));assertThat(festival.eventEndDate()).isEqualTo(start.plusDays(2));}
 @Test void excludesNonOverlappingFestival(){LocalDate start=LocalDate.of(2026,9,10);festivals.setFestivals(List.of(new com.travel.meomulkyung.itinerary.external.FestivalProvider.Festival(100L,"Past Festival",start.minusDays(4),start.minusDays(1),null,null),new com.travel.meomulkyung.itinerary.external.FestivalProvider.Festival(101L,"Future Festival",start.plusDays(3),start.plusDays(4),null,null)));var response=service.create(user(),request(start,2));assertThat(response.days()).flatExtracting(day->day.items()).extracting("type").doesNotContain("FESTIVAL");}
 @Test void createsRegularItineraryWhenNoFestivalExists(){var response=service.create(user(),request(1));assertThat(response.days()).hasSize(2);assertThat(response.days()).flatExtracting(day->day.items()).extracting("type").doesNotContain("FESTIVAL");assertThat(response.warnings()).isEmpty();}
 @Test void createsItineraryAndReturnsWarningWhenFestivalProviderFails(){festivals.fail();var response=service.create(user(),request(1));assertThat(response.days()).hasSize(2);assertThat(response.warnings()).containsExactly(new ItineraryResponses.Warning("FESTIVAL_DATA_UNAVAILABLE","축제 정보를 일정에 반영하지 못했습니다."));}
 @Test void festivalIsNotReplaceable(){LocalDate start=LocalDate.of(2026,9,10);festivals.setFestivals(List.of(new com.travel.meomulkyung.itinerary.external.FestivalProvider.Festival(102L,"Festival",start,start,null,null)));var response=service.create(user(),request(start,1));assertThat(response.days()).flatExtracting(day->day.items()).filteredOn(item->item.type().equals("FESTIVAL")).extracting("replaceable").containsOnly(false);}
 @Test void rejectsFestivalReplacementWithConflict(){LocalDate start=LocalDate.of(2026,9,10);festivals.setFestivals(List.of(new com.travel.meomulkyung.itinerary.external.FestivalProvider.Festival(103L,"Festival",start,start,null,null)));Long uid=user();Long itineraryId=service.create(uid,request(start,1)).itineraryId();Itinerary itinerary=itineraries.findDetailById(itineraryId).orElseThrow();ItineraryItem festival=itinerary.getItems().stream().filter(item->item.getItemType()==ItineraryItemType.FESTIVAL).findFirst().orElseThrow();assertThatThrownBy(()->service.replace(uid,itineraryId,festival.getId(),new ItineraryRequests.Replace(false))).isInstanceOf(ItineraryException.class).extracting("status").isEqualTo(org.springframework.http.HttpStatus.CONFLICT);}
}
